using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly string[] _categoryLabels;
    private readonly EvaluationResponse _evaluationMetrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // With a small dataset, train on all data and evaluate with cross-validation
        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract category labels from the trained model's key-value mapping
        var labelColumn = dataView.Schema[nameof(TicketData.Category)];
        var keyValues = new VBuffer<ReadOnlyMemory<char>>();

        // Run a dummy prediction to get label ordering from the score column
        var transformedData = _model.Transform(dataView);
        var scoreColumn = transformedData.Schema["Score"];
        if (scoreColumn.Type is Microsoft.ML.Data.VectorDataViewType vectorType)
        {
            var slotNames = new VBuffer<ReadOnlyMemory<char>>();
            transformedData.Schema["Score"].GetSlotNames(ref slotNames);
            _categoryLabels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
        }
        else
        {
            _categoryLabels = ["Billing", "General", "Technical"];
        }

        // Cross-validate to get realistic metrics
        var cvResults = _mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3);
        var avgMetrics = cvResults.Select(r => r.Metrics).ToList();

        _evaluationMetrics = new EvaluationResponse
        {
            MacroAccuracy = (float)avgMetrics.Average(m => m.MacroAccuracy),
            MicroAccuracy = (float)avgMetrics.Average(m => m.MicroAccuracy),
            LogLoss = (float)avgMetrics.Average(m => m.LogLoss),
            LogLossReduction = (float)avgMetrics.Average(m => m.LogLossReduction),
            PerCategory = BuildPerCategoryMetrics(avgMetrics)
        };
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
        {
            scores[_categoryLabels[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            Scores = scores
        };
    }

    public EvaluationResponse GetEvaluationMetrics() => _evaluationMetrics;

    private List<CategoryMetric> BuildPerCategoryMetrics(
        List<Microsoft.ML.Data.MulticlassClassificationMetrics> metricsList)
    {
        var categories = new List<CategoryMetric>();
        if (metricsList.Count == 0 || metricsList[0].PerClassLogLoss.Count == 0)
            return categories;

        for (int i = 0; i < _categoryLabels.Length; i++)
        {
            var avgPerClassLogLoss = metricsList
                .Where(m => i < m.PerClassLogLoss.Count)
                .Average(m => m.PerClassLogLoss[i]);

            categories.Add(new CategoryMetric
            {
                Category = _categoryLabels[i],
                // Per-class log loss is the best per-class metric available from cross-validation
                Precision = Math.Round(1.0 - avgPerClassLogLoss, 4),
                Recall = Math.Round(1.0 - avgPerClassLogLoss, 4),
                F1Score = Math.Round(1.0 - avgPerClassLogLoss, 4)
            });
        }

        return categories;
    }
}

