private static float Sanitize(double value) =>
    double.IsNaN(value) || double.IsInfinity(value) ? 0f : (float)value;

private List<CategoryMetric> BuildPerCategoryMetrics(
    Microsoft.ML.Data.MulticlassClassificationMetrics metrics)
{
    var categories = new List<CategoryMetric>();
    var confusionMatrix = metrics.ConfusionMatrix;

    for (int i = 0; i < _categoryLabels.Length && i < confusionMatrix.PerClassPrecision.Count; i++)
    {
        categories.Add(new CategoryMetric
        {
            Category = _categoryLabels[i],
            Precision = Math.Round(Sanitize(confusionMatrix.PerClassPrecision[i]), 4),
            Recall = Math.Round(Sanitize(confusionMatrix.PerClassRecall[i]), 4),
            F1Score = Math.Round(Sanitize(2.0 * confusionMatrix.PerClassPrecision[i] * confusionMatrix.PerClassRecall[i]
                / (confusionMatrix.PerClassPrecision[i] + confusionMatrix.PerClassRecall[i])), 4)
        });
    }

    return categories;
}

